create or replace function private.notes_can_access_folder(p_folder_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=pg_catalog,public,private as $$
select p_folder_id is not null and (private.notes_is_platform_owner(p_user_id)
or exists(with recursive ancestors(id,parent_folder_id,owner_id) as (select f.id,f.parent_folder_id,f.owner_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id,parent.owner_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from ancestors a where a.owner_id=p_user_id)
or exists(with recursive ancestors(id,parent_folder_id) as (select f.id,f.parent_folder_id from public.notes_folders f where f.id=p_folder_id union all select parent.id,parent.parent_folder_id from public.notes_folders parent join ancestors a on a.parent_folder_id=parent.id) select 1 from public.notes_collaborators c join ancestors a on a.id=c.folder_id where c.resource_type='FOLDER' and c.invited_user_id=p_user_id and c.status='ACCEPTED'));$$;